        this.haze.emit(
          p,
          v.velocity.x * 0.12 + r() * 0.4,
          0.1,
          v.velocity.z * 0.12 + r() * 0.4,
          2.5 + Math.random() * 1.5,
          0.6 + Math.random() * 0.4,
          9 + Math.random() * 6,
          this.dustColor,
          0.06 + Math.random() * 0.03,
