  async treeBenchmark(
    opts: { frames?: number; step?: number; withoutTrees?: boolean; download?: boolean } = {},
  ): Promise<TreeBenchReport> {
    const frames = opts.frames ?? 1200;
    const step = opts.step ?? 0.5;
